  const w2y = Math.cos(my*0.022+t*0.45)*8+Math.sin(mx*0.018-t*0.35)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [140+Math.sin(t*0.55)*110,70+Math.cos(t*0.42)*50,0.075,2.1,0.8],
    [340+Math.cos(t*0.48)*100,170+Math.sin(t*0.65)*55,0.09,1.8,1.1],
    [240+Math.sin(t*0.32+2)*150,110+Math.cos(t*0.5+1)*95,0.055,2.4,0.6],
    [100+Math.cos(t*0.75+1)*90,190+Math.sin(t*0.58+3)*65,0.11,1.6,1.3],
    [380+Math.sin(t*0.38+4)*95,50+Math.cos(t*0.85+2)*75,0.065,2.7,0.5],
    [220+Math.cos(t*0.33+5)*130,210+Math.sin(t*0.52)*85,0.085,2.0,0.9],
    [60+Math.sin(t*0.62+3)*70,130+Math.cos(t*0.48+4)*60,0.1,1.5,1.2],
    [420+Math.cos(t*0.44+2)*80,100+Math.sin(t*0.72+1)*70,0.07,2.3,0.7]
  ];
  let aS=0,iS=0,dS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const att=Math.exp(-d*0.003)*w;
    aS+=Math.sin(d*f-t*sp)*att;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*att;
    dS+=Math.sin(d*f*0.4-t*sp*0.3+3.0)*att*0.5;
  }
  const act=aS/5.5,inh=iS/5.5,dif=dS/5.5;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.75)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2
    +Math.sin((sx+sy)*0.11+t*2.3)*0.18
    +Math.sin((sx-sy)*0.095-t*1.9)*0.18
    +Math.sin(sx*0.065+t*1.6)*Math.cos(sy*0.055-t*1.3)*0.12;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
