  const reaction=Math.tanh((act-inh*0.65+bg*0.28+spiral+dif*0.4+moire*0.15)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.095+t)*0.45+Math.sin(sx*0.2-t*0.7)*Math.sin(sy*0.18+t*0.5)*0.3)*1.4)*0.25;
  const micro=Math.sin(sx*0.35+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
  const blend=reaction*0.65+cell*0.25+micro*0.1,v=blend*0.5+0.5;
  const pal=[
    [5,12,58],[10,45,95],[12,85,115],[18,135,130],[45,165,135],
    [140,185,95],[210,190,60],[225,145,55],[215,95,60],[185,55,70],
    [130,35,65],[75,20,55],[35,12,48],[5,12,58]
